export class RecordingClient {
  readonly #device: Device

  constructor(device: Device) {
    this.#device = device
  }

  /**
   * @param recordingToken - The `RecordingToken` of every request
   * @returns The operations that take a `RecordingToken`, without it in the request
   */
  forRecording(recordingToken: string): RecordingTokenClient {
    return new RecordingTokenClient(this.#device, recordingToken)
  }

  /**
   * Returns the capabilities of the recording service. The result is returned in a typed answer.
   *
   * @param request - The `GetServiceCapabilities` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetServiceCapabilitiesResponse`
   */
  getServiceCapabilities(
    request?: GetServiceCapabilitiesRequest,
    options?: CallOptions
  ): Promise<GetServiceCapabilitiesResponse> {
    return this.#device.call(GetServiceCapabilities, request, options)
  }

  /**
   * GetRecordings shall return a description of all the recordings in the device. This description shall
   * include a list of all the tracks for each recording.
   *
   * @param request - The `GetRecordings` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingsResponse`
   */
  getRecordings(request?: GetRecordingsRequest, options?: CallOptions): Promise<GetRecordingsResponse> {
    return this.#device.call(GetRecordings, request, options)
  }

  /**
   * CreateRecording shall create a new recording. The new recording shall be created with a track for
   * each supported TrackType see Recording Control Spec. This method is optional. It shall be available
   * if the Recording/DynamicRecordings capability is TRUE. When successfully completed, CreateRecording
   * shall have created three tracks with the following configurations: TrackToken TrackType VIDEO001
   * Video AUDIO001 Audio META001 Metadata All tracks created as response to a CreateRecording request
   * shall have the MaximumRetentionTime set to 0 (unlimited), and the Description set to the empty
   * string, by default.
   *
   * @param request - The `CreateRecording` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `CreateRecordingResponse`
   */
  createRecording(request: CreateRecordingRequest, options?: CallOptions): Promise<CreateRecordingResponse> {
    return this.#device.call(CreateRecording, request, options)
  }

  /**
   * DeleteRecording shall delete a recording object. Whenever a recording is deleted, the device shall
   * delete all the tracks that are part of the recording, and it shall delete all the Recording Jobs
   * that record into the recording. For each deleted recording job, the device shall also delete all the
   * receiver objects associated with the recording job that are automatically created using the
   * AutoCreateReceiver field of the recording job configuration structure and are not used in any other
   * recording job. This method is optional. It shall be available if the Recording/DynamicRecordings
   * capability is TRUE.
   *
   * @param request - The `DeleteRecording` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `DeleteRecordingResponse`
   */
  deleteRecording(request: DeleteRecordingRequest, options?: CallOptions): Promise<DeleteRecordingResponse> {
    return this.#device.call(DeleteRecording, request, options)
  }

  /**
   * GetRecordingConfiguration shall retrieve the recording configuration for a recording.
   *
   * @param request - The `GetRecordingConfiguration` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingConfigurationResponse`
   */
  getRecordingConfiguration(
    request: GetRecordingConfigurationRequest,
    options?: CallOptions
  ): Promise<GetRecordingConfigurationResponse> {
    return this.#device.call(GetRecordingConfiguration, request, options)
  }

  /**
   * SetRecordingConfiguration shall change the configuration of a recording.
   *
   * @param request - The `SetRecordingConfiguration` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetRecordingConfigurationResponse`
   */
  setRecordingConfiguration(
    request: SetRecordingConfigurationRequest,
    options?: CallOptions
  ): Promise<SetRecordingConfigurationResponse> {
    return this.#device.call(SetRecordingConfiguration, request, options)
  }

  /**
   * GetRecordingOptions returns information for a recording identified by the RecordingToken. The
   * information includes the number of additonal tracks as well as recording jobs that can be
   * configured.
   *
   * @param request - The `GetRecordingOptions` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingOptionsResponse`
   */
  getRecordingOptions(
    request: GetRecordingOptionsRequest,
    options?: CallOptions
  ): Promise<GetRecordingOptionsResponse> {
    return this.#device.call(GetRecordingOptions, request, options)
  }

  /**
   * This method shall create a new track within a recording. This method is optional. It shall be
   * available if the Recording/DynamicTracks capability is TRUE. A TrackToken in itself does not
   * uniquely identify a specific track. Tracks within different recordings may have the same TrackToken.
   *
   * @param request - The `CreateTrack` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `CreateTrackResponse`
   */
  createTrack(request: CreateTrackRequest, options?: CallOptions): Promise<CreateTrackResponse> {
    return this.#device.call(CreateTrack, request, options)
  }

  /**
   * DeleteTrack shall remove a track from a recording. All the data in the track shall be deleted. This
   * method is optional. It shall be available if the Recording/DynamicTracks capability is TRUE.
   *
   * @param request - The `DeleteTrack` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `DeleteTrackResponse`
   */
  deleteTrack(request: DeleteTrackRequest, options?: CallOptions): Promise<DeleteTrackResponse> {
    return this.#device.call(DeleteTrack, request, options)
  }

  /**
   * GetTrackConfiguration shall retrieve the configuration for a specific track.
   *
   * @param request - The `GetTrackConfiguration` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetTrackConfigurationResponse`
   */
  getTrackConfiguration(
    request: GetTrackConfigurationRequest,
    options?: CallOptions
  ): Promise<GetTrackConfigurationResponse> {
    return this.#device.call(GetTrackConfiguration, request, options)
  }

  /**
   * SetTrackConfiguration shall change the configuration of a track.
   *
   * @param request - The `SetTrackConfiguration` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetTrackConfigurationResponse`
   */
  setTrackConfiguration(
    request: SetTrackConfigurationRequest,
    options?: CallOptions
  ): Promise<SetTrackConfigurationResponse> {
    return this.#device.call(SetTrackConfiguration, request, options)
  }

  /**
   * GetRecordingJobs shall return a list of all the recording jobs in the device.
   *
   * @param request - The `GetRecordingJobs` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingJobsResponse`
   */
  getRecordingJobs(request?: GetRecordingJobsRequest, options?: CallOptions): Promise<GetRecordingJobsResponse> {
    return this.#device.call(GetRecordingJobs, request, options)
  }

  /**
   * CreateRecordingJob shall create a new recording job. The JobConfiguration returned from
   * CreateRecordingJob shall be identical to the JobConfiguration passed into CreateRecordingJob, except
   * for the ReceiverToken and the AutoCreateReceiver. In the returned structure, the ReceiverToken shall
   * be present and valid and the AutoCreateReceiver field shall be omitted.
   *
   * @param request - The `CreateRecordingJob` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `CreateRecordingJobResponse`
   */
  createRecordingJob(request: CreateRecordingJobRequest, options?: CallOptions): Promise<CreateRecordingJobResponse> {
    return this.#device.call(CreateRecordingJob, request, options)
  }

  /**
   * DeleteRecordingJob removes a recording job. It shall also implicitly delete all the receiver objects
   * associated with the recording job that are automatically created using the AutoCreateReceiver field
   * of the recording job configuration structure and are not used in any other recording job.
   *
   * @param request - The `DeleteRecordingJob` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `DeleteRecordingJobResponse`
   */
  deleteRecordingJob(request: DeleteRecordingJobRequest, options?: CallOptions): Promise<DeleteRecordingJobResponse> {
    return this.#device.call(DeleteRecordingJob, request, options)
  }

  /**
   * GetRecordingJobConfiguration shall return the current configuration for a recording job.
   *
   * @param request - The `GetRecordingJobConfiguration` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingJobConfigurationResponse`
   */
  getRecordingJobConfiguration(
    request: GetRecordingJobConfigurationRequest,
    options?: CallOptions
  ): Promise<GetRecordingJobConfigurationResponse> {
    return this.#device.call(GetRecordingJobConfiguration, request, options)
  }

  /**
   * SetRecordingJobConfiguration shall change the configuration for a recording job.
   * SetRecordingJobConfiguration shall implicitly delete any receiver objects that were created
   * automatically if they are no longer used as a result of changing the recording job configuration.
   *
   * @param request - The `SetRecordingJobConfiguration` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetRecordingJobConfigurationResponse`
   */
  setRecordingJobConfiguration(
    request: SetRecordingJobConfigurationRequest,
    options?: CallOptions
  ): Promise<SetRecordingJobConfigurationResponse> {
    return this.#device.call(SetRecordingJobConfiguration, request, options)
  }

  /**
   * SetRecordingJobMode shall change the mode of the recording job. Using this method shall be
   * equivalent to retrieving the recording job configuration, and writing it back with a different mode.
   *
   * @param request - The `SetRecordingJobMode` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetRecordingJobModeResponse`
   */
  setRecordingJobMode(
    request: SetRecordingJobModeRequest,
    options?: CallOptions
  ): Promise<SetRecordingJobModeResponse> {
    return this.#device.call(SetRecordingJobMode, request, options)
  }

  /**
   * GetRecordingJobState returns the state of a recording job. It includes an aggregated state, and
   * state for each track of the recording job.
   *
   * @param request - The `GetRecordingJobState` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingJobStateResponse`
   */
  getRecordingJobState(
    request: GetRecordingJobStateRequest,
    options?: CallOptions
  ): Promise<GetRecordingJobStateResponse> {
    return this.#device.call(GetRecordingJobState, request, options)
  }
}

export class RecordingTokenClient {
  readonly #device: Device
  readonly #recordingToken: string

  constructor(device: Device, recordingToken: string) {
    this.#device = device
    this.#recordingToken = recordingToken
  }

  /**
   * DeleteRecording shall delete a recording object. Whenever a recording is deleted, the device shall
   * delete all the tracks that are part of the recording, and it shall delete all the Recording Jobs
   * that record into the recording. For each deleted recording job, the device shall also delete all the
   * receiver objects associated with the recording job that are automatically created using the
   * AutoCreateReceiver field of the recording job configuration structure and are not used in any other
   * recording job. This method is optional. It shall be available if the Recording/DynamicRecordings
   * capability is TRUE.
   *
   * @param request - The `DeleteRecording` request without `recordingToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `DeleteRecordingResponse`
   */
  deleteRecording(
    request?: Omit<DeleteRecordingRequest, 'recordingToken'>,
    options?: CallOptions
  ): Promise<DeleteRecordingResponse> {
    return this.#device.call(DeleteRecording, { ...request, recordingToken: this.#recordingToken }, options)
  }

  /**
   * GetRecordingConfiguration shall retrieve the recording configuration for a recording.
   *
   * @param request - The `GetRecordingConfiguration` request without `recordingToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingConfigurationResponse`
   */
  getRecordingConfiguration(
    request?: Omit<GetRecordingConfigurationRequest, 'recordingToken'>,
    options?: CallOptions
  ): Promise<GetRecordingConfigurationResponse> {
    return this.#device.call(GetRecordingConfiguration, { ...request, recordingToken: this.#recordingToken }, options)
  }

  /**
   * SetRecordingConfiguration shall change the configuration of a recording.
   *
   * @param request - The `SetRecordingConfiguration` request without `recordingToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetRecordingConfigurationResponse`
   */
  setRecordingConfiguration(
    request: Omit<SetRecordingConfigurationRequest, 'recordingToken'>,
    options?: CallOptions
  ): Promise<SetRecordingConfigurationResponse> {
    return this.#device.call(SetRecordingConfiguration, { ...request, recordingToken: this.#recordingToken }, options)
  }

  /**
   * GetRecordingOptions returns information for a recording identified by the RecordingToken. The
   * information includes the number of additonal tracks as well as recording jobs that can be
   * configured.
   *
   * @param request - The `GetRecordingOptions` request without `recordingToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingOptionsResponse`
   */
  getRecordingOptions(
    request?: Omit<GetRecordingOptionsRequest, 'recordingToken'>,
    options?: CallOptions
  ): Promise<GetRecordingOptionsResponse> {
    return this.#device.call(GetRecordingOptions, { ...request, recordingToken: this.#recordingToken }, options)
  }

  /**
   * This method shall create a new track within a recording. This method is optional. It shall be
   * available if the Recording/DynamicTracks capability is TRUE. A TrackToken in itself does not
   * uniquely identify a specific track. Tracks within different recordings may have the same TrackToken.
   *
   * @param request - The `CreateTrack` request without `recordingToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `CreateTrackResponse`
   */
  createTrack(
    request: Omit<CreateTrackRequest, 'recordingToken'>,
    options?: CallOptions
  ): Promise<CreateTrackResponse> {
    return this.#device.call(CreateTrack, { ...request, recordingToken: this.#recordingToken }, options)
  }

  /**
   * DeleteTrack shall remove a track from a recording. All the data in the track shall be deleted. This
   * method is optional. It shall be available if the Recording/DynamicTracks capability is TRUE.
   *
   * @param request - The `DeleteTrack` request without `recordingToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `DeleteTrackResponse`
   */
  deleteTrack(
    request: Omit<DeleteTrackRequest, 'recordingToken'>,
    options?: CallOptions
  ): Promise<DeleteTrackResponse> {
    return this.#device.call(DeleteTrack, { ...request, recordingToken: this.#recordingToken }, options)
  }

  /**
   * GetTrackConfiguration shall retrieve the configuration for a specific track.
   *
   * @param request - The `GetTrackConfiguration` request without `recordingToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetTrackConfigurationResponse`
   */
  getTrackConfiguration(
    request: Omit<GetTrackConfigurationRequest, 'recordingToken'>,
    options?: CallOptions
  ): Promise<GetTrackConfigurationResponse> {
    return this.#device.call(GetTrackConfiguration, { ...request, recordingToken: this.#recordingToken }, options)
  }

  /**
   * SetTrackConfiguration shall change the configuration of a track.
   *
   * @param request - The `SetTrackConfiguration` request without `recordingToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetTrackConfigurationResponse`
   */
  setTrackConfiguration(
    request: Omit<SetTrackConfigurationRequest, 'recordingToken'>,
    options?: CallOptions
  ): Promise<SetTrackConfigurationResponse> {
    return this.#device.call(SetTrackConfiguration, { ...request, recordingToken: this.#recordingToken }, options)
  }
}
